def f(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    others=[c for c,n in cnt.most_common() if c not in (bg,0)]
    blocks={m:[(i,j) for i in range(H-1) for j in range(W-1)
              if all(g[i+a][j+b]==m for a,b in ((0,0),(0,1),(1,0),(1,1)))
              and g[i+1][j+1]!=bg or True] for m in others}
    return bg,sorted(others,key=lambda m:-sum(1 for _ in blocks[m]))
